import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"35、【晉】 坤下離上","description":"周易闡真 - 35、【晉】 坤下離上","frontmatter":{"title":"35、【晉】 坤下離上","description":"周易闡真 - 35、【晉】 坤下離上"},"headers":[],"relativePath":"classics/chanzhen/036.md","filePath":"classics/chanzhen/036.md"}'),s={name:"classics/chanzhen/036.md"};function n(c,p,i,o,l,h){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：晉，進也，明出地上。順而麗乎大明，柔進而上行，是以康侯用錫馬蕃庶，晝日三接也。</p></blockquote><h1 id="_35、【晉】-坤下離上" tabindex="-1">35、【晉】 坤下離上 <a class="header-anchor" href="#_35、【晉】-坤下離上" aria-label="Permalink to “35、【晉】 坤下離上”">​</a></h1><p>初六：晉如摧如，貞吉。罔孚，裕，無咎。</p><p>六二：晉如愁如，貞吉。受茲介福，於其王母。</p><p>六三：眾允，悔亡。</p><p>九四：晉如鼫鼠，貞厲。</p><p>六五：悔亡，失得勿恤。往吉，無不利。</p><p>上九：晉其角，維用伐邑。厲吉，無咎，貞吝。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：明出地上，晉。君子以自昭明德。</p><p>晉者，進也。上離日，下坤地，是日出地上也。日本明，地本暗，明出地上，由暗而明，晉之象也。</p><p>君子有見於此，知日入於地，又能出地；人昧其德，亦能明德。以是自昭其明德焉。昭者，明也。明德者，即人本來良知良能之靈性。此性本來真空妙有，炯炯不昧，一交後天氣質之性，由明入暗，失其本體矣。但不明由於自，昭明亦由於自，是在自昭不昭耳。若果自知昭明，即便能明，急須下手修為，除去一切積滯，解脫萬般塵情，從實地上用工夫，戒慎恐懼，防微杜漸，人心自去，道心自彰，氣質自化，真性自現，仍是當年圓陀陀、光灼灼、淨倮倮、赤灑灑一個虛靈不昧物事了也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>鼫，音石。</p><p>晉者，進也。卦德上離明，下坤順，由順而生明，用明而行順，順時順理，其明日增，故謂晉。此自誠而明，進火之卦，承上遁卦而來。遁者，止其健，而不輕用健也。不輕用健則心虛，心虛則燭照覺察，戒慎恐懼，不為物慾所瞞，黑中有白，神明自來矣。</p><p>人之本來良知良能之性，炯炯不昧，其德本明。因交後天，識神用事，人心起而道心藏，良知之健，變為不良之健，良能之順，變為不良之順。心與物交，錮閉靈竅，神明有昧矣。</p><p>聖人教人進火者，由不明而復進於明耳。進明之功，非順道不能。順者，順時順理，常存道心，不生人心，知之能之，無一不良。天之賦人者良，人之順天者亦良。天人合發，元神不昧，自誠而明，其明日增，由小而大，自微而著，漸進於高明遠見之處，有象於康侯，用錫馬蕃庶，晝日三接也。</p><p>康侯者，安泰寧靜之侯。馬在午，屬於離明之象。蕃庶者，地所生，屬於坤順之象。晝日者，日之明，明在上也。三接者，地之順，順在下也。</p><p>人之良知良能之真心，為一身之主，如一國之有康侯也。真心不背於天良，用明用順，如康侯用錫馬蕃庶也。</p><p>由順而生明，以明而行順，如晝日三接也。三接者，乃再三之順，不順而必至於順，其中有閒邪存誠之功。閒邪存誠，人心順、道心彰，誠則明矣，明則誠矣。誠明兼該，明明德而止於止善，進火之功盡矣。</p><p>初六，在明之初，大理未明，宜靜不宜動，是以晉如摧如，守貞而吉也。夫守貞而吉者，以其未能自信，先須窮理，充裕於內，運火自無差錯之咎矣。此未進明、先求其明也。</p><p>六二，處於三陰昏暗之中，不但不能增明，而且有以蔽明，是以晉如愁如也。然柔而守正，不為假陰所惑，不進而亦不愁，是以貞而得吉。蓋能貞則致虛守靜，真陰現象，假陰自化，如受茲介福於其王母矣。此處不明、不遽進明也。</p><p>六三，不能自下而順，乃自上而順，似乎不正而致悔。然性柔志剛，不順陰而順陽，借他家之明，以濟我家之暗，我順他而他即順我，是以眾允其進，有悔可亡。此己不明、順人之明也。</p><p>九四，居於明體，已進於明矣。但在二陰之內，明藏暗中，又應初陰，明而有私，邪正不分，是非相雜，以是進明如鼫鼠夜行，所見不大，其行不遠。雖用明得正，終有危厲。此剛而有私之明也。</p><p>六五，居於二陽之內，既明其我家不明，又明其他家有明，借剛濟柔，本有悔者而悔可亡。悔由於心之不虛，若知虛心，則以己求人，即能實腹。既實其腹，則吉凶止足，如在掌上，可以失得勿恤，直行無疑，往而進火下功，吉無不利者。此虛以招實之明也。</p><p>上九，剛強自勝，只知進明，不知虛明，是以維用伐邑也。邑為私邑，伐邑即克己之功。克己之功，虛人心也。若不虛心，獨恃其剛，強制強伏，必危厲而後得吉，得無咎。以是用明，雖克己得正，亦屬勉強，不由自然，未免取吝於大方。此剛而高亢之明也。</p><p>然則進明運火之道，未明必先求其明，既明又當虛其明，虛實並用，剛柔相當。自誠而明，明本於誠，其明日進日高，用之不盡，取之不竭，大地裡黃芽長遍，滿世界金花開綻，無處不可用明，無處能傷其明矣。</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
